    {"name": "write", "arguments": {"path": "rest_api.py", "overwrite": True, "content": "class RestAPI:\n    def __init__(self, database=None):\n        self.users = {} if database is None else database\n\n    @staticmethod\n    def _user(name):\n        return {\"name\": name, \"owes\": {}, \"owed_by\": {}, \"balance\": 0.0}\n\n    def _balance(self, user):\n        user[\"balance\"] = round(sum(user[\"owed_by\"].values()) - sum(user[\"owes\"].values()), 2)\n        return user\n\n    def get(self, url, payload=None):\n        if url != \"/users\":\n            return None\n        names = sorted(self.users) if payload is None else sorted(payload.get(\"users\", []))\n        return {\"users\": [self._balance(self.users[name]) for name in names if name in self.users]}\n\n    def post(self, url, payload=None):\n        payload = payload or {}\n        if url == \"/add\":\n            name = payload[\"user\"]\n            if name not in self.users:\n                self.users[name] = self._user(name)\n            return self._balance(self.users[name])\n        if url == \"/iou\":\n            lender, borrower, amount = payload[\"lender\"], payload[\"borrower\"], payload[\"amount\"]\n            if lender not in self.users:\n                self.users[lender] = self._user(lender)\n            if borrower not in self.users:\n                self.users[borrower] = self._user(borrower)\n            owing = self.users[borrower][\"owes\"]\n            owed = self.users[lender][\"owed_by\"]\n            reverse_owed = self.users[borrower][\"owed_by\"]\n            reverse_owing = self.users[lender][\"owes\"]\n            if lender in reverse_owed:\n                paid = min(amount, reverse_owed[lender])\n                remainder = round(amount - paid, 2)\n                reverse_owed[lender] = round(reverse_owed[lender] - paid, 2)\n                reverse_owing[borrower] = round(reverse_owing[borrower] - paid, 2)\n                if reverse_owed[lender] == 0:\n                    del reverse_owed[lender]\n                    del reverse_owing[borrower]\n                if remainder:\n                    owing[lender] = round(owing.get(lender, 0) + remainder, 2)\n                    owed[borrower] = round(owed.get(borrower, 0) + remainder, 2)\n            else:\n                owing[lender] = round(owing.get(lender, 0) + amount, 2)\n                owed[borrower] = round(owed.get(borrower, 0) + amount, 2)\n            return {\"users\": [self._balance(self.users[name]) for name in sorted([lender, borrower])] }\n        return None\n"}},
